UPDATE learning_path SET path_code=COALESCE(path_code,CONCAT('legacy_path_',id)),current_version=COALESCE(current_version,1),target_knowledge_point_id=COALESCE(target_knowledge_point_id,(SELECT knowledge_point_id FROM learning_path_item i WHERE i.path_id=learning_path.id AND i.knowledge_point_id IS NOT NULL ORDER BY order_no DESC LIMIT 1));
UPDATE learning_path_item i JOIN learning_path_version v ON v.path_id=i.path_id AND v.version=1 SET i.path_version_id=v.id,i.path_step_code=COALESCE(i.path_step_code,CONCAT('legacy_ps_',i.id)),i.stage='LEARNING',i.reason_code='LEGACY_SEQUENCE' WHERE i.item_type='knowledge';
