INSERT INTO learning_path_version(path_id,version,path_mode,based_on_profile_version,graph_version,policy_version,model_version,status,change_reason,correlation_id,created_at) SELECT id,1,'LEGACY_MIGRATED',0,'legacy_mysql','path_policy_v1','legacy_sequence','ACTIVE','STAGE10_MIGRATION','stage10-migration',created_at FROM learning_path ON DUPLICATE KEY UPDATE path_id=path_id;
